sealed class SlowStore:HttpMessageHandler{
 internal TaskCompletionSource Entered=new(TaskCreationOptions.RunContinuationsAsynchronously),Release=new(TaskCreationOptions.RunContinuationsAsynchronously);
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Entered.TrySetResult();await Release.Task;token.ThrowIfCancellationRequested();return new(HttpStatusCode.OK){Content=new StringContent("{}")};}}
